function showNew(){const used=data.shipments.map(function(s){return s.truck}),truck=backendCatalog&&backendCatalog.trucks.length?backendCatalog.trucks[0].plate:Array.from({length:120},function(_,i){return "ATL-"+String(i+1).padStart(3,"0")}).find(function(c){return !used.includes(c)&&data.vehicles.some(function(v){return v.code===c&&v.status==="IDLE"})})||"ATL-120";document.getElementById("modalBody").innerHTML='<div class="border-b p-5" style="border-color:var(--line)"><div class="flex justify-between"><div><p class="accent text-[10px] font-bold uppercase tracking-widest">AndesAdmin</p><h2 class="mt-1 text-xl font-semibold">Programar nuevo envío</h2><p class="muted mt-1 text-xs">Distancia y ETA estimadas según la ruta.</p></div><button data-action="close" class="btn quiet">×</button></div></div><form id="newform" class="space-y-3 p-5"><div class="grid gap-3 sm:grid-cols-2"><label class="text-xs">Cliente<input class="field mt-1" name="client" required placeholder="Nombre del cliente"></label><label class="text-xs">Correo del cliente<input class="field mt-1" name="email" type="email" value="cliente@andeslink.pe" placeholder="cliente@empresa.pe"></label><label class="text-xs">Carga<input class="field mt-1" name="cargo" required placeholder="Tipo de carga"></label><label class="text-xs">Conductor<select class="field mt-1" name="driver">'+(backendCatalog?backendCatalog.drivers.map(function(d){return"<option value=\""+esc(d.email)+"\">"+esc(d.name)+"</option>"}).join(""):drivers.map(function(d){return"<option>"+d+"</option>"}).join(""))+'</select></label><label class="text-xs">Camión<input class="field mt-1" name="truck" required value="'+truck+'"></label><label class="text-xs">Origen<select class="field mt-1" name="origin">'+Object.keys(cities).map(function(c){return"<option>"+c+"</option>"}).join("")+'</select></label><label class="text-xs">Destino<select class="field mt-1" name="destination">'+Object.keys(cities).filter(function(c){return c!=="Lima"}).map(function(c){return"<option "+(c==="Arequipa"?"selected":"")+">"+c+"</option>"}).join("")+'</select></label><label class="text-xs">Velocidad promedio<input class="field mt-1" name="speed" type="number" value="55" min="25" max="90"></label></div><div id="preview" class="rounded-xl bg-emerald-50 p-3 text-sm text-emerald-950"></div><div class="flex justify-end gap-2"><button type="button" data-action="close" class="btn quiet">Cancelar</button><button class="btn primary">Crear programación →</button></div></form>';bind();document.getElementById("modal").showModal();routePreview()}
function routePreview(){const f=document.getElementById("newform");if(!f)return;const km=dist(cities[f.origin.value],cities[f.destination.value]),h=km/(Number(f.speed.value)||55);document.getElementById("preview").innerHTML="<b>⌖ "+f.origin.value+" → "+f.destination.value+"</b>　<b>"+km+" km</b><div class='mt-1 text-xs'>ETA estimada: <b>"+fmt(eta(h))+"</b> · "+h.toFixed(1)+" h</div>"}
