async function create(e){e.preventDefault();const f=new FormData(e.target),origin=f.get("origin"),destination=f.get("destination"),driver=f.get("driver");if(accessToken){try{const body={clientEmail:f.get("email")||"cliente@andeslink.pe",driverEmail:backendCatalog&&backendCatalog.drivers.some(function(x){return x.email===driver})?driver:"conductor@andeslink.pe",truckPlate:f.get("truck"),cargo:f.get("cargo"),weightTon:1,declaredValueUsd:0,origin:origin,destination:destination,scheduledDeparture:new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,19),averageSpeedKmh:Number(f.get("speed"))||55};const created=await apiRequest("/api/admin/shipments",{method:"POST",body:JSON.stringify(body)});document.getElementById("modal").close();await syncApiState();toast("Envío programado",created.trackingCode+" · ETA "+fmt(created.eta));return}catch(err){toast("No se pudo programar",err.message);return}}const km=dist(cities[origin],cities[destination]),hours=km/(Number(f.get("speed"))||55),id="AT-"+String(2401+data.shipments.length).padStart(4,"0"),s={id:id,client:f.get("client"),email:f.get("email")||"",driver:driver,driverEmail:driver==="Diego Quispe"?"conductor@andeslink.pe":"",truck:f.get("truck"),cargo:f.get("cargo"),origin:origin,destination:destination,distance:km,eta:eta(hours),status:"PLANNED",progress:0,lat:cities[origin].lat,lon:cities[origin].lon};data.shipments.unshift(s);const vehicle=data.vehicles.find(function(v){return v.code===s.truck});if(vehicle){vehicle.driver=driver;vehicle.shipmentId=s.id}save({kind:"SHIPMENT_CREATED",shipment:s});document.getElementById("modal").close();render();toast("Envío programado",id+" · "+km+" km · ETA "+fmt(s.eta))}
